import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Inject,
  Param,
  ParseIntPipe,
  Patch,
  Post,
  Query,
} from '@nestjs/common';
import { FormValidationPipe } from '@nestvexa/forms';
import {
  createTaskAdapter,
  taskQueryAdapter,
  updateTaskAdapter,
} from './task.dto.js';
import type { CreateTaskDto, TaskQuery, UpdateTaskDto } from './task.dto.js';
import type { Task, TaskPage } from './task.repository.js';
import { TaskService } from './task.service.js';

/**
 * REST routes generated by `nestvexa make:resource --crud`. Invalid input is a
 * 400 with field errors; add guards before production.
 */
@Controller('task')
export class TaskController {
  constructor(@Inject(TaskService) private readonly task: TaskService) {}

  @Get()
  list(
    @Query(new FormValidationPipe(taskQueryAdapter)) query: TaskQuery,
  ): Promise<TaskPage> {
    return this.task.list(query);
  }

  @Get(':id')
  show(@Param('id', ParseIntPipe) id: number): Promise<Task> {
    return this.task.get(id);
  }

  @Post()
  create(
    @Body(new FormValidationPipe(createTaskAdapter)) body: CreateTaskDto,
  ): Promise<Task> {
    return this.task.create(body);
  }

  @Patch(':id')
  update(
    @Param('id', ParseIntPipe) id: number,
    @Body(new FormValidationPipe(updateTaskAdapter)) body: UpdateTaskDto,
  ): Promise<Task> {
    return this.task.update(id, body);
  }

  @Delete(':id')
  @HttpCode(204)
  remove(@Param('id', ParseIntPipe) id: number): Promise<void> {
    return this.task.remove(id);
  }
}
